parameters.jsCode:
// PHI — valida dados Google + ELEVA IDENTIDADE ao topo (ADR-33, Item A)
// Este fluxo NAO executa otimizacoes — apenas valida dados.
// Regra ADR-33 / ADR-003: so ACRESCENTA identidade; nao altera agregados nem series.

const items = $input.all();

// 1. Sem resposta da requisicao HTTP
if (!items || items.length === 0 || !items[0].json) {
  return {
    json: {
      has_data: false,
      data_source: 'google_ads_api',
      validation_status: 'no_request_response',
      reason: 'A requisicao ao Google Ads falhou ou retornou vazio'
    }
  };
}

const data = items[0].json;

// 2. Primeiro resultado do Google (a serie diaria ja foi pre-agregada upstream;
//    results[0] serve so para VALIDAR que veio dado)
const googleData = data.results && data.results.length > 0 ? data.results[0] : null;

// Helper: extrai a identidade estavel da campanha (Contrato de Identidade, ADR-33)
function extrairIdentidade(gd) {
  const c = (gd && gd.campaign) || {};
  const rn = c.resourceName || '';
  const idFromRn = rn ? rn.split('/').pop() : null;
  return {
    platform: 'google',
    entity_level: 'campaign',
    entity_id: c.id || idFromRn || null,
    entity_name: c.name || null,
    entity_resource: rn || null
  };
}

if (!googleData) {
  return {
    json: {
      ...data,
      has_data: false,
      validation_status: 'no_results',
      data_source: 'google_ads_api',
      reason: 'O Google Ads retornou 0 resultados para este ID de campanha nesta data'
    }
  };
}

// Identidade elevada ao topo (a partir daqui todo item carrega quem ele e)
const ident = extrairIdentidade(googleData);

// 3. Validar campos obrigatorios (camelCase v22+: costMicros)
const metrics = googleData.metrics || {};
const requiredFields = ['impressions', 'clicks', 'costMicros'];
const missingFields = requiredFields.filter(field =>
  metrics[field] === null || metrics[field] === undefined
);

if (missingFields.length > 0) {
  return {
    json: {
      ...data,
      ...ident,
      has_data: false,
      validation_status: 'incomplete',
      data_source: 'google_ads_api',
      missing_fields: missingFields,
      reason: `Campos de metricas ausentes no retorno da API: ${missingFields.join(', ')}`
    }
  };
}

// 4. Dados validos e prontos
return {
  json: {
    ...data,
    ...ident,
    has_data: true,
    validation_status: 'valid',
    date_used: data.attempted_date || data.date_d1,
    data_source: 'google_ads_api',
    fallback_used: !!data.fallback_active
  }
};

// Nome: "Valida Dados - Meta"
// ADR-33 B2: eleva a identidade Meta ao topo (o HTTP apaga a identidade do item);
// fonte = Code clean propriedades. Nunca emitir item sem identidade (Opcao A).
const items = $input.all();

const cp = (($('Code clean propriedades').first() || {}).json) || {};
const identMeta = {
  platform: 'meta',
  entity_level: 'ad',
  entity_id: cp.clean_id_meta_ads != null ? String(cp.clean_id_meta_ads) : null,
  entity_name: cp.clean_nome_anuncio || cp.clean_nome_campanha || null,
  page_id: cp.clean_notion_id_ads || null,
  meta_campaign_id: cp.clean_id_meta_campaign != null ? String(cp.clean_id_meta_campaign) : null
};

if (!items || items.length === 0 || !items[0].json.data || items[0].json.data.length === 0) {
  return {
    json: {
      ...(items[0]?.json || {}),
      ...identMeta,
      has_data: false,
      data_source: 'meta_ads_api',
      validation_status: 'no_results',
      reason: 'O Meta Ads retornou 0 resultados para esta data'
    }
  };
}

return {
  json: {
    ...items[0].json,
    ...identMeta,
    has_data: true,
    validation_status: 'valid',
    data_source: 'meta_ads_api',
    date_used: items[0].json.date_d1
  }
};

// Este fluxo NAO executa otimizacoes - apenas valida dados
// ADR-33 B2: eleva a identidade Meta ao topo (fonte = Code clean propriedades).
const item = $input.first();
const inputJson = item?.json ?? {};
const rows = Array.isArray(inputJson.data) ? inputJson.data : [];

const cp = (($('Code clean propriedades').first() || {}).json) || {};
const identMeta = {
  platform: 'meta',
  entity_level: 'ad',
  entity_id: cp.clean_id_meta_ads != null ? String(cp.clean_id_meta_ads) : null,
  entity_name: cp.clean_nome_anuncio || cp.clean_nome_campanha || null,
  page_id: cp.clean_notion_id_ads || null,
  meta_campaign_id: cp.clean_id_meta_campaign != null ? String(cp.clean_id_meta_campaign) : null
};

if (rows.length === 0) {
  return {
    json: {
      ...inputJson,
      ...identMeta,
      has_data: false,
      data_source: 'meta_ads_api',
      validation_status: 'no_results',
      reason: 'O Meta Ads retornou 0 resultados para D-2'
    }
  };
}

return {
  json: {
    ...inputJson,
    ...identMeta,
    has_data: true,
    validation_status: 'valid',
    data_source: 'meta_ads_api',
    date_used: inputJson.date_d2,
    fallback_used: true
  }
};

// Este fluxo NÃO executa otimizações - apenas calcula desvio para classificação.
// CONVENÇÃO: desvio POSITIVO = PIOR que a meta (vale para qualquer métrica).
// [2026-08-08] desvio INDEFINIDO (null) != desvio 0. Mesma familia da regra 8 do BLOCO COMUM
// (conversions=0 => CPA/ROAS indefinidos): ausencia de informacao nunca vira valor neutro.
// [2026-08-08] v_d1/v_3d/v_7d saem do ITEM corrente. O .first() foi removido: devolvia sempre
// o 1o item do lote, vazando numeros de um anuncio para outro (visto na exec 26161, run 3).
const items = $input.all();
const returnData = [];

// Margem de contribuição padrão por modelo de negócio (fallback sem campo no Notion). break-even = 1/margem.
const MARGEM_PADRAO = {
  'E-commerce': 0.30, 'Ecommerce': 0.30,
  'SaaS': 0.80,
  'Infoproduto': 0.85, 'Infoprodutos': 0.85,
  'Serviços': 0.50, 'Servicos': 0.50, 'Serviço Local': 0.50,
  'B2B': 0.50, 'Lead': 0.50, 'Lead Gen': 0.50, 'Geração de Leads': 0.50
};
const MARGEM_FALLBACK = 0.30;
const MAIOR_MELHOR = ['ROAS', 'CTR', 'Taxa de Conversão', 'Taxa de Conversao'];

// metrica-mae -> [chave em metricas_calculadas.d7, campo plano do item]
const METRIC_KEYS = {
  'CPA': ['cpa', 'cpa_7d'],
  'CPL': ['cpl', 'cpl_7d'],
  'CPC': ['cpc', 'cpc_7d'],
  'CPM': ['cpm', 'cpm_7d'],
  'ROAS': ['roas', 'roas_7d'],
  'CTR': ['ctr', 'ctr_7d'],
  'Taxa de Conversão': ['cvr', 'taxa_conversao_7d'],
  'Taxa de Conversao': ['cvr', 'taxa_conversao_7d']
};

// 0 / vazio / NaN significam "nao sei" aqui, nao "zero".
const numOrNull = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) && n !== 0 ? n : null;
};

for (const item of items) {
  const data = item.json;
  const config = data.sop_config || {};
  const tipo = config.metric_principal || data.tipo_metrica || 'CPA';
  const isMaiorMelhor = MAIOR_MELHOR.includes(tipo);
  const keys = METRIC_KEYS[tipo] || METRIC_KEYS['CPA'];

  // --- valores do PROPRIO item (sem cross-node) ---
  const calcCtx = data.calc_context || {};
  const d7src = (data.metricas_calculadas && data.metricas_calculadas.d7) || {};

  let v_7d = numOrNull(data.v_7d !== undefined ? data.v_7d : calcCtx.v_7d);
  if (v_7d === null) v_7d = numOrNull(d7src[keys[0]]);
  if (v_7d === null) v_7d = numOrNull(data[keys[1]]);
  if (v_7d === null) v_7d = numOrNull(data.valor_real);

  // D1/D3 so existem se o item os trouxer. Sem fallback cross-node: sem valor => INDEFINIDO.
  const v_d1 = numOrNull(data.v_d1 !== undefined ? data.v_d1 : calcCtx.v_d1);
  const v_3d = numOrNull(data.v_3d !== undefined ? data.v_3d : calcCtx.v_3d);

  const margem = Number(
    data.clean_margem_contribuicao ||
    MARGEM_PADRAO[data.clean_modelo_negocio] ||
    MARGEM_PADRAO[data.clean_objetivo] ||
    MARGEM_FALLBACK
  );
  const break_even_roas = margem > 0 ? parseFloat((1 / margem).toFixed(2)) : null;

  let meta = Number(config.meta_valor || data.meta_valor || 0);
  if (tipo === 'ROAS' && (!meta || meta <= 0) && break_even_roas) {
    meta = break_even_roas;
  }

  if ((!meta || meta === 0) && v_d1 === null && v_3d === null && v_7d === null) {
    returnData.push({ json: { ...data, v_d1, v_3d, v_7d, analise_desvios: { error: "Meta não definida ou dados não encontrados" }, deviation_status: 'missing_data_for_calculation' } });
    continue;
  }

  // Devolve SEMPRE {valor, desvio, desvio_motivo}. desvio = null quando indefinido.
  const calcDesvio = (valor) => {
    if (!meta || meta === 0) return { valor, desvio: null, desvio_motivo: 'sem_meta' };
    if (valor === null) return { valor, desvio: null, desvio_motivo: 'sem_valor' };
    const d = isMaiorMelhor ? ((meta - valor) / meta) * 100 : ((valor - meta) / meta) * 100;
    return { valor, desvio: parseFloat(d.toFixed(2)), desvio_motivo: 'ok' };
  };
  const calcTendencia = (v3, v7) => {
    if (v3 === null || v7 === null) return null;
    return parseFloat((isMaiorMelhor ? ((v7 - v3) / v7) * 100 : ((v3 - v7) / v7) * 100).toFixed(2));
  };

  const d1_res = calcDesvio(v_d1);
  const d3_res = calcDesvio(v_3d);
  const d7_res = calcDesvio(v_7d);
  const tend_proxy = calcTendencia(v_3d, v_7d);

  // Prefere a tendência REAL (série diária BigQuery) quando disponível; senão usa a janela da API.
  const tendReal = (data.tendencia_real !== undefined && data.tendencia_real !== null) ? Number(data.tendencia_real) : null;
  const tendenciaFinal = tendReal !== null ? tendReal : tend_proxy;
  const tendenciaFonte = tendReal !== null
    ? (data.tendencia_metodo || 'bigquery')
    : (tend_proxy === null ? 'indisponivel' : 'janela_api');

  returnData.push({
    json: {
      ...data,
      v_d1, v_3d, v_7d,
      analise_desvios: {
        meta_aplicada: meta,
        tipo_metric: tipo,
        direcao: isMaiorMelhor ? 'maior_melhor' : 'menor_melhor',
        margem_contribuicao: margem,
        break_even_roas,
        d1: d1_res,
        d3: d3_res,
        d7: d7_res,
        tendencia_3d_vs_7d: tendenciaFinal,
        tendencia_proxy_api: tend_proxy,
        tendencia_fonte: tendenciaFonte,
        tendencia_n_dias: data.tendencia_n_dias ?? null
      },
      deviation_status: 'calculated_success'
    }
  });
}

return returnData;

// Classificação informativa (NÃO executa otimizações). Convenção: desvio positivo = pior.
// Inclui gate de significância estatística e limiares por objetivo (doc §3, §5.7, §7).
const items = $input.all();
const output = [];

// [2026-08-08] ESCADA DE EVIDENCIA (era: gate binario fixo em 7D).
// O volume passa a decidir a CONFIANCA da leitura, nao SE existe leitura.
// Motivo: um limiar absoluto de 7d travava permanentemente contas de baixo
// orcamento (ex.: CLI-4/KIL exigiria ~3x o orcamento inteiro para abrir o gate),
// congelando score=50 e status="Em aprendizado" em anuncios com anos de veiculacao.
// PLENO   -> afirma com certeza (limiar historico preservado).
// PARCIAL -> afirma como hipotese, registrando a janela de evidencia usada.
// NENHUM  -> so aqui deixa de classificar.
const MIN_CLICKS_PLENO = 100;
const MIN_CONV_PLENO = 10;
const MIN_CLICKS_PARCIAL = 30;
const MIN_CONV_PARCIAL = 3;
// Abaixo disso o anuncio e genuinamente novo -> "Em aprendizado" e verdade.
const DIAS_APRENDIZADO = 14;

// Limite de desvio (%) para virar "Crítico", por objetivo. Fallback = 'default' (preserva 15).
const LIMITE_CRITICO = {
  'default': 15,
  'Conversão': 12, 'Conversões': 12, 'Vendas': 12,
  'Leads': 20, 'Geração de Leads': 20,
  'Tráfego': 30, 'Trafego': 30,
  'Reconhecimento': 40, 'Alcance': 40
};

for (const item of items) {
  const data = item.json;
  const analise = data.analise_desvios;
  const config = data.sop_config || {};

  const numv = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

  // --- Idade do anuncio: separa "novo de verdade" de "sem volume" ---
  let diasDesdeLancamento = null;
  try {
    const dl = $('Loop Over Items').item.json.properties?.['Data de Lançamento']?.date?.start;
    if (dl) diasDesdeLancamento = Math.floor((Date.now() - new Date(dl).getTime()) / 86400000);
  } catch (e) {}
  const anuncioNovo = diasDesdeLancamento !== null && diasDesdeLancamento < DIAS_APRENDIZADO;

  // --- Volume por janela (defensivo entre Google e Meta) ---
  // [2026-08-08 fase4] .first() cross-node REMOVIDO. Este no roda 4x (todos os anuncios) mas
  // 'HTTP Request Google Ontem (D7)' so 2x (Google): o .first() dava a resposta de um anuncio
  // Google a outro anuncio. Alem disso o item aqui NAO carrega id estavel (clean_* ja
  // espalhados por 'Code Valida Dados'), entao nao ha como casar por id nem por indice
  // alinhado com seguranca. Os campos raw_*_7d do proprio item sao a fonte autoritativa;
  // se forem 0/0 o anuncio genuinamente nao teve volume 7d -> cai no gate abaixo (correto).
  const clicks7d = numv(data.raw_clicks_7d ?? data.clicks_7d);
  const conv7d = numv(data.raw_conversions_7d ?? data.conversions_7d);
  const clicks30d = numv(data.clicks_30d);
  const conv30d = numv(data.conversions_30d);

  const tipo = (analise && analise.tipo_metric) || config.metric_principal || 'CPA';
  const dependeConversao = ['CPA', 'CPL', 'ROAS', 'Taxa de Conversão', 'Taxa de Conversao'].includes(tipo);

  // ROAS sem receita rastreada nao e julgavel (valor de conversao placeholder).
  const roasSemReceita = (tipo === 'ROAS') && (data.receita_placeholder_7d === true);

  const atinge = (cl, cv, minCl, minCv) => cl >= minCl && (!dependeConversao || cv >= minCv);
  const janelas = [
    { nome: '7d', clicks: clicks7d, conv: conv7d },
    { nome: '30d', clicks: clicks30d, conv: conv30d }
  ];

  let nivel = 'nenhum', janelaEvidencia = null, confianca = 'sem_base';
  const pleno = janelas.find((j) => atinge(j.clicks, j.conv, MIN_CLICKS_PLENO, MIN_CONV_PLENO));
  if (pleno) {
    nivel = 'pleno'; janelaEvidencia = pleno.nome; confianca = 'certeza';
  } else {
    const parciais = janelas.filter((j) => atinge(j.clicks, j.conv, MIN_CLICKS_PARCIAL, MIN_CONV_PARCIAL));
    if (parciais.length) {
      nivel = 'parcial'; janelaEvidencia = parciais[parciais.length - 1].nome; confianca = 'hipotese';
    }
  }

  // [2026-08-08] desvio INDEFINIDO (null) tem de ser tratado ANTES de qualquer comparacao.
  // Em JS `null <= 0` e TRUE: sem esta guarda, `if (d7 <= 0) status = "OK"` classificaria
  // "nao sei" como Bom, e `Math.max(null, 0)` daria score 100. E o bug que estamos matando.
  const rawD7 = analise && analise.d7 ? analise.d7.desvio : null;
  const rawD1 = analise && analise.d1 ? analise.d1.desvio : null;
  const d7num = Number.isFinite(Number(rawD7)) && rawD7 !== null ? Number(rawD7) : null;
  const d1num = Number.isFinite(Number(rawD1)) && rawD1 !== null ? Number(rawD1) : null;
  const desvioIndefinido = d7num === null;
  const desvioMotivo = (analise && analise.d7 && analise.d7.desvio_motivo) || (analise && analise.error ? 'sem_dados' : 'sem_valor');

  const significancia = {
    nivel, janela_evidencia: janelaEvidencia, confianca,
    desvio_indefinido: desvioIndefinido,
    desvio_motivo: desvioIndefinido ? desvioMotivo : 'ok',
    clicks_7d: clicks7d, conversions_7d: conv7d,
    clicks_30d: clicks30d, conversions_30d: conv30d,
    min_pleno: { clicks: MIN_CLICKS_PLENO, conversoes: MIN_CONV_PLENO },
    min_parcial: { clicks: MIN_CLICKS_PARCIAL, conversoes: MIN_CONV_PARCIAL },
    dias_desde_lancamento: diasDesdeLancamento,
    anuncio_novo: anuncioNovo,
    roas_sem_receita: roasSemReceita,
    suficiente: nivel === 'pleno'
  };

  // Casos em que nao se classifica desempenho (inclui desvio indefinido).
  if (!analise || !analise.d7 || nivel === 'nenhum' || roasSemReceita || desvioIndefinido) {
    output.push({
      json: {
        ...data,
        final_status: anuncioNovo ? "Em Aprendizado" : "Sem Dados",
        final_score: null,
        classe_score: "N/A",
        status_emoji: anuncioNovo ? "🌱" : "⏳",
        significancia
      }
    });
    continue;
  }

  // Aqui d7num e garantidamente finito (o ramo acima ja capturou o indefinido).
  const d7 = d7num;
  // [2026-08-08 fase4] REGRA MORTA: D1 nao e produzido neste fluxo. 'Code Cálcula Métricas'
  // so gera janelas 7d e 30d; nunca ha valor D-1, entao d1 e SEMPRE null e o ajuste "pico
  // D-1" (mais abaixo) e o desconto de score por d1 NUNCA disparam. Mantidos null-safe e
  // dormentes de proposito: nao calcular D1/D3 agora (seria escopo novo, sem demanda). Se um
  // dia o fluxo passar a coletar D-1 por anuncio, as regras voltam a valer sozinhas.
  const d1 = d1num;                       // sempre null neste fluxo; guardas abaixo o respeitam
  const tRaw = analise.tendencia_3d_vs_7d;
  const tendencia = Number.isFinite(Number(tRaw)) && tRaw !== null ? Number(tRaw) : null;

  const objetivo = data.clean_objetivo || data.objetivo || 'default';
  const limiteCritico = LIMITE_CRITICO[objetivo] || LIMITE_CRITICO['default'];

  // --- Classificação base por desvio 7D (positivo = pior) ---
  let status;
  if (d7 <= 0) status = "OK";
  else if (d7 <= limiteCritico) status = "Atenção";
  else status = "Crítico";

  // Ajuste por tendência (positivo = piorou). null = indefinido, nao ajusta.
  if (status === "OK" && tendencia !== null && tendencia > 10) status = "Atenção";
  // Ajuste por pico D-1. null = indefinido, nao ajusta.
  if (status === "OK" && d1 !== null && d1 > 30) status = "Atenção";

  // --- Score 0-100 ---
  let score = 100;
  score -= Math.min(Math.max(d7, 0) * 2, 40);
  if (tendencia !== null && tendencia > 0) score -= Math.min(tendencia, 30);
  if (d1 !== null && d1 > 20) score -= 10;
  score = Math.max(Math.round(score), 0);

  let classeScore = "Crítico";
  if (score >= 80) classeScore = "Estável";
  else if (score >= 60) classeScore = "Atenção";
  else if (score >= 40) classeScore = "Instável";

  const emojiMap = { "OK": "✅", "Atenção": "⚠️", "Crítico": "🚨", "Sem Dados": "⏳", "Dados Insuficientes": "🔍" };

  output.push({
    json: {
      ...data,
      final_status: status,
      final_score: score,
      classe_score: classeScore,
      status_emoji: emojiMap[status] || "❓",
      significancia
    }
  });
}

return output;

const input = $input.first().json;

const num = (value) => {
  const n = Number(value ?? 0);
  return Number.isFinite(n) ? n : 0;
};

const sqlString = (value) => String(value ?? '').replace(/'/g, "''");

const firstResult = (nodeName) => {
  try {
    return $(nodeName).item.json.results?.[0] || {};
  } catch (e) {
    return {};
  }
};

const getNodeJson = (nodeName) => {
  try {
    return $(nodeName).item.json || {};
  } catch (e) {
    return {};
  }
};

const metricsOf = (row) => row.metrics || {};

const clean = getNodeJson('Code clean propriedades');
const validation = getNodeJson('Code Valida Dados');

const rD1 = firstResult('HTTP Request Google Ontem (D1)');
const rD3 = firstResult('HTTP Request Google Ontem (D3)');
const rD7 = firstResult('HTTP Request Google Ontem (D7)');
const mD1 = metricsOf(rD1);
const mD3 = metricsOf(rD3);
const mD7 = metricsOf(rD7);

const googleCampaignId = rD1.campaign?.id || '';
const googleAdsetId = rD1.adGroup?.id || '';
const googleAdId = rD1.adGroupAd?.ad?.id || '';

if (!googleCampaignId || !googleAdsetId || !googleAdId) {
  return [{
    json: {
      ...input,
      _bq_sql: '',
      _skip_ingestion: true,
      _skip_reason: !googleAdId ? 'sem_ad_id (PMAX ou GAQL vazia)' : (!googleCampaignId ? 'sem_campaign_id' : 'sem_adset_id')
    }
  }];
}

const clientId = clean.clean_client_slug || input.client_id || '';
const campaignId = `GADS-${googleCampaignId}`;
const adsetId = String(googleAdsetId);
const adId = String(googleAdId);
const executionId = clean.source_execution_id || input.source_execution_id ||
  `EXEC-DE-${new Date().toISOString().replace(/[-:TZ.]/g, '').slice(0, 14)}`;
const adName = rD1.adGroupAd?.ad?.name || clean.clean_nome_anuncio || '';
const adStatus = rD1.adGroupAd?.status || '';

const cost = num(mD1.costMicros) / 1000000;
const conversions = num(mD1.conversions);
const clicks = num(mD1.clicks);
const impressions = num(mD1.impressions);
const convValue = num(mD1.conversionsValue);
const cost3d = num(mD3.costMicros) / 1000000;
const conversions3d = num(mD3.conversions);
const convValue3d = num(mD3.conversionsValue);
const cost7d = num(mD7.costMicros) / 1000000;
const conversions7d = num(mD7.conversions);
const convValue7d = num(mD7.conversionsValue);

const dataSource = validation.data_source || 'google_ads_api';
const platform = clean.clean_plataforma === 'Google Ads'
