// Serie diaria (BigQuery): o SQL e montado AQUI, nao dentro do node BigQuery (CLAUDE.md regra 8).
// Modo runOnceForEachItem: 1 item entra -> 1 item sai. 'Code Tendencia Real' pareia por INDICE.
const data = $json;
const num = (v) => { const n = Number(v || 0); return Number.isFinite(n) ? n : 0; };
const esc = (v) => String(v == null ? '' : v).replace(/'/g, "''");

// O id da CAMPANHA vem de 'Code clean propriedades' via pareamento de item.
// Usar clean_id_google_camp: clean_id_google e o id do ANUNCIO em campanha nao-PMAX
// (so coincide com o da campanha quando e PMAX).
let clean = null;
let motivo = 'ok';
try {
  clean = $('Code clean propriedades').item.json;
} catch (e) {
  motivo = 'pareamento_indisponivel';
}

let campaign_id = '';
if (clean) {
  const idG = num(clean.clean_id_google_camp);
  const idM = num(clean.clean_id_meta_campaign);
  if (idG > 0) campaign_id = 'GADS-' + idG;
  else if (idM > 0) campaign_id = 'META-' + idM;
  else motivo = 'sem_id_campanha';
}

// Nunca emitir SQL vazio (o node BigQuery quebraria). Sem id -> query valida que retorna 0 linhas.
const idSql = esc(campaign_id || 'SEM-ID');
const TZ = "CURRENT_DATE('America/Sao_Paulo')";
const J3 = 'date >= DATE_SUB(' + TZ + ', INTERVAL 3 DAY)';
const JP3 = 'date < DATE_SUB(' + TZ + ', INTERVAL 3 DAY) AND date >= DATE_SUB(' + TZ + ', INTERVAL 6 DAY)';
const s3 = (col, alias) => 'SUM(IF(' + J3 + ', ' + col + ', 0)) AS ' + alias;
const sp3 = (col, alias) => 'SUM(IF(' + JP3 + ', ' + col + ', 0)) AS ' + alias;

const _bq_sql_serie = [
  'SELECT COUNT(*) AS n_dias',
  s3('cost', 'cost_3'),
  s3('conversions', 'conv_3'),
  s3('clicks', 'clicks_3'),
  s3('impressions', 'impr_3'),
  '0 AS rev_3',
  sp3('cost', 'cost_prev3'),
  sp3('conversions', 'conv_prev3'),
  sp3('clicks', 'clicks_prev3'),
  sp3('impressions', 'impr_prev3'),
  '0 AS rev_prev3'
].join(', ')
  + ' FROM `project-0e7c58d4-656f-49e8-807.phi_prod.raw_campaign_data`'
  + " WHERE campaign_id = '" + idSql + "'"
  + ' AND date >= DATE_SUB(' + TZ + ', INTERVAL 21 DAY)';

return { json: { ...data, bq_campaign_id: campaign_id, _bq_sql_serie, _serie_motivo: motivo } };

// Tendência real do histórico diário (BigQuery): métrica dos últimos 3 dias vs 3 dias anteriores.
// Pareado por índice com o nó de prep. Suporta ROAS via coluna conversions_value. Fallback < 4 dias.
const prep = $('Code Prep Tendência').all();
const rows = $input.all();
const num = (x) => Number(x || 0);
const out = [];

for (let i = 0; i < prep.length; i++) {
  const ctx = prep[i].json;
  const r = (rows[i] && rows[i].json) || {};
  const tipo = ctx.sop_config?.metric_principal || 'CPA';

  const metricaJanela = (cost, conv, clicks, impr, rev) => {
    if (tipo === 'ROAS') return cost > 0 ? rev / cost : null;
    if (tipo === 'CPC') return clicks > 0 ? cost / clicks : null;
    if (tipo === 'CTR') return impr > 0 ? (clicks / impr) * 100 : null;
    if (tipo === 'Taxa de Conversão') return clicks > 0 ? (conv / clicks) * 100 : null;
    return conv > 0 ? cost / conv : null;        // CPA / CPL
  };

  const nDias = num(r.n_dias);
  let tendencia_real = null;
  let metodo = 'sem_historico';

  // [2026-08-08] rotulo honesto: 'sem_historico' era usado para dois casos diferentes.
  //   nDias < 4                          -> sem_historico (nao ha serie)
  //   nDias >= 4 mas metrica indefinida  -> sem_metrica_na_janela (ex.: conv_3 = 0 => CPA indefinido)
  if (nDias >= 4) {
    const recente = metricaJanela(num(r.cost_3), num(r.conv_3), num(r.clicks_3), num(r.impr_3), num(r.rev_3));
    const anterior = metricaJanela(num(r.cost_prev3), num(r.conv_prev3), num(r.clicks_prev3), num(r.impr_prev3), num(r.rev_prev3));
    metodo = 'sem_metrica_na_janela';
    if (recente != null && anterior != null && anterior > 0) {
      const MAIOR_MELHOR = ['CTR', 'Taxa de Conversão', 'ROAS'];
      const bruto = ((recente - anterior) / anterior) * 100; // positivo = subiu
      // padroniza: positivo = PIOROU
      tendencia_real = MAIOR_MELHOR.includes(tipo) ? parseFloat((-bruto).toFixed(2)) : parseFloat(bruto.toFixed(2));
      metodo = 'bigquery_3d_vs_3d';
    }
  }

  out.push({ json: { ...ctx, tendencia_real, tendencia_metodo: metodo, tendencia_n_dias: nDias } });
}

return out;

const items = $input.all();
const output = [];

// Divisão segura: nunca retorna NaN nem Infinity.
const safeDiv = (a, b) => {
  const n = Number(a) || 0;
  const d = Number(b) || 0;
  if (!d) return 0;
  const r = n / d;
  return Number.isFinite(r) ? r : 0;
};
const round2 = (v) => parseFloat((Number(v) || 0).toFixed(2));

for (const item of items) {
  const root = item.json;
  // Agora nivel 'ad': cada ad retorna uma linha em root.data.
  const data = (root.data && root.data.length > 0) ? root.data[0] : null;

  if (!data) {
    output.push(item);
    continue;
  }

  // --- Extração base ---
  const cost = Number(data.spend || 0);
  const impressions = Number(data.impressions || 0);
  const clicks = Number(data.clicks || 0);
  const frequencia = Number(data.frequency || 0);
  const objective = String(data.objective || '');

  // Helper: soma o valor das ações cujo action_type esteja na lista.
  const sumActions = (arr, types) => {
    if (!Array.isArray(arr)) return 0;
    return arr
      .filter((a) => types.includes(a.action_type))
      .reduce((acc, a) => acc + (Number(a.value) || 0), 0);
  };

  // --- B3: extração inteligente por objetivo (determinística, sem IA) ---
  const CONV_POR_OBJETIVO = {
    OUTCOME_SALES: ['offsite_conversion.fb_pixel_purchase', 'purchase', 'omni_purchase'],
    OUTCOME_LEADS: ['lead', 'offsite_conversion.fb_pixel_lead', 'onsite_conversion.lead_grouped'],
    OUTCOME_ENGAGEMENT: ['onsite_conversion.messaging_conversation_started_7d', 'onsite_conversion.total_messaging_connection'],
    OUTCOME_TRAFFIC: ['link_click'],
    OUTCOME_AWARENESS: ['reach'],
  };
  const CONV_FALLBACK = ['offsite_conversion.fb_pixel_purchase', 'purchase', 'omni_purchase', 'lead'];
  const tiposConversao = CONV_POR_OBJETIVO[objective] || CONV_FALLBACK;
  const conversions = sumActions(data.actions, tiposConversao);

  const message_conversations = sumActions(data.actions, [
    'onsite_conversion.messaging_conversation_started_7d',
    'onsite_conversion.total_messaging_connection',
  ]);

  const revenue = sumActions(data.action_values, [
    'offsite_conversion.fb_pixel_purchase', 'purchase', 'omni_purchase',
  ]);

  // --- Vídeo (podem vir vazios em anúncios sem vídeo: tratado como 0) ---
  const video_started = sumActions(data.video_play_actions, ['video_view']);
  const video_p50 = sumActions(data.video_p50_watched_actions, ['video_view']);
  const video_p100 = sumActions(data.video_p100_watched_actions, ['video_view']);

  // --- B2: métricas derivadas (todas com guarda anti NaN/Infinity) ---
  const ctr = round2(safeDiv(clicks, impressions) * 100);
  const cpc = round2(safeDiv(cost, clicks));
  const cpa = round2(safeDiv(cost, conversions));
  const convRate = round2(safeDiv(conversions, clicks) * 100);
  const cpm = round2(safeDiv(cost, impressions) * 1000);
  const roas = round2(safeDiv(revenue, cost));
  const hook_rate = round2(safeDiv(video_started, impressions) * 100);
  const hold_rate = round2(safeDiv(video_p100, video_started) * 100);

  output.push({
    json: {
      ...root, // Preserva IDs do Notion e contexto
      calculado: {
        ad_id: data.ad_id || '',
        ad_name: data.ad_name || '',
        adset_id: data.adset_id || '',
        campaign_id: data.campaign_id || '',
        objective,
        custo_real: round2(cost),
        impressoes: impressions,
        frequencia,
        cliques: clicks,
        conversoes: conversions,
        todas_conversoes: conversions,
        message_conversations,
        receita: round2(revenue),
        cpa_atual: cpa,
        cpa_alvo_google: Number(root.meta_valor || 0),
        taxa_conversao: convRate,
        ctr,
        cpc,
        cpm,
        roas,
        hook_rate,
        hold_rate,
        video_iniciados: video_started,
        video_50: video_p50,
        video_completos: video_p100,
        quality_ranking: data.quality_ranking || '',
        engagement_rate_ranking: data.engagement_rate_ranking || '',
        conversion_rate_ranking: data.conversion_rate_ranking || '',
        score_otimizacao: "N/A",
        status_aprendizado: data.learning_stage_info?.status || 'N/A'
      }
    }
  });
}

return output;

