const extractPlainText = (value) => {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number') return String(value);
  if (Array.isArray(value)) return value.map(extractPlainText).filter(Boolean).join(', ');
  if (value.plain_text) return value.plain_text;
  if (value.name) return value.name;
  if (value.title) return extractPlainText(value.title);
  if (value.rich_text) return extractPlainText(value.rich_text);
  if (value.select) return extractPlainText(value.select);
  if (value.status) return extractPlainText(value.status);
  if (value.multi_select) return extractPlainText(value.multi_select);
  if (value.formula) return extractPlainText(value.formula.string ?? value.formula.number ?? value.formula.boolean ?? value.formula.date);
  if (value.rollup) return extractPlainText(value.rollup.array ?? value.rollup.string ?? value.rollup.number ?? value.rollup.date);
  if (value.unique_id) return [value.unique_id.prefix, value.unique_id.number].filter((part) => part !== undefined && part !== null && part !== '').join('-');
  return '';
};

const extractNumber = (value) => {
  if (!value) return 0;
  if (typeof value === 'number') return value;
  if (typeof value === 'string') {
    const parsed = Number(value.replace(',', '.'));
    return Number.isFinite(parsed) ? parsed : 0;
  }
  const candidate = value.number ?? value.formula?.number ?? value.rollup?.number ?? value.unique_id?.number;
  if (candidate !== undefined && candidate !== null) return Number(candidate) || 0;
  const text = extractPlainText(value);
  const parsed = Number(String(text).replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : 0;
};

const extractBoolean = (value) => Boolean(value?.checkbox ?? value?.formula?.boolean ?? false);
const extractDate = (value) => value?.date?.start || value?.formula?.date?.start || value?.rollup?.date?.start || '';

const ad = firstJsonFromNode('Loop Over Items');
const campanha = firstJsonFromNode('Get database campanhas');
