  clean_notion_id_adset: extractPlainText(conjuntoProps['notion_id_adset']) || extractPlainText(adProps['id_adset_padrao']),
  clean_notion_id_ads: extractPlainText(adProps['notion_id_ad']) || ad.id || '',
  clean_id_google_camp: extractNumber(campanhaProps['id_google_camp']),
  clean_id_google_adset: extractNumber(conjuntoProps['adset_id_google']) || extractNumber(adProps['id_google_adset']),
  clean_id_google_ad: extractNumber(adProps['id_google_ad']) || extractNumber(adProps['google_ad_id']),
  clean_customer_id_google: extractNumber(conjuntoProps['customer_id_google']) || extractNumber(campanhaProps['id_google_account']) || extractNumber(adProps['id_google_account']),
  clean_id_meta_account: extractNumber(adProps['id_meta_account']) || extractNumber(conjuntoProps['meta_account_id']) || extractNumber(campanhaProps['id_meta_account']),
  clean_id_meta_campaign: extractNumber(campanhaProps['id_meta_camp']) || extractNumber(adProps['id_meta_campaing']) || extractNumber(adProps['id_meta_campaign']),
  clean_id_meta_ads: extractNumber(adProps['id_meta_ads']) || extractNumber(adProps['ID Meta Ads']) || extractNumber(adProps['ad_id_meta']),
  clean_client_slug: extractPlainText(campanhaProps['client_slug']) || extractPlainText(conjuntoProps['sigla_cliente']) || extractPlainText(adProps['Sigla Cliente']),
  clean_nome_campanha: extractPlainText(campanhaProps['Nome Campanha']) || extractPlainText(campanhaProps['Nome da campanha']),
  clean_nome_conjunto: extractPlainText(conjuntoProps['adset_name']) || extractPlainText(conjuntoProps['Nome']),
  clean_nome_anuncio: extractPlainText(adProps['ad_name']) || extractPlainText(adProps['Nome']),
  clean_plataforma: plataforma,
  clean_modelo_negocio: extractPlainText(campanhaProps['Modelo de Negócio']),
  clean_metrica_mae: extractPlainText(campanhaProps['Metrica-Mae']) || extractPlainText(campanhaProps['Métrica-Mãe']) || extractPlainText(adProps['Metrica-Mae']) || extractPlainText(adProps['Métrica-Mãe']),
  clean_meta_metrica_mae: extractNumber(adProps['Meta Metrica-Mae']) || extractNumber(adProps['Meta Métrica-Mãe']) || extractNumber(campanhaProps['Meta da Metrica-mae']) || extractNumber(campanhaProps['Meta da Métrica-mãe']),
  clean_cpa_alvo: extractNumber(campanhaProps['CPA Alvo']),
  clean_periodo_otimizacao_aberto: extractBoolean(adProps['Periodo de Otimizacao?']) || extractBoolean(adProps['Período de Otimização?']) || extractBoolean(campanhaProps['Otimizacao Ativa?']) || extractBoolean(campanhaProps['Otimização Ativa?']),
  clean_data_inicio: extractDate(conjuntoProps['Inicio']) || extractDate(campanhaProps['Data de Inicio']) || extractDate(adProps['Data de Lancamento']) || extractDate(adProps['Data de Lançamento']),
  clean_data_conclusao: extractDate(conjuntoProps['Termino']) || extractDate(conjuntoProps['Término']) || extractDate(campanhaProps['Data de conclusao']) || extractDate(campanhaProps['Data de conclusão']),
  clean_ultima_otimizacao: extractDate(campanhaProps['Ultima Otimizacao']) || extractDate(campanhaProps['Última Otimização']) || extractDate(adProps['ad_ultima_execucao']),
};

const isGoogle = /google/i.test(String(clean.clean_plataforma || ''));
const namesForDetection = [clean.clean_nome_campanha, clean.clean_nome_anuncio, clean.clean_nome_conjunto].join(' ').toUpperCase();
const structuralPmax = clean.clean_id_google_ad > 0 && clean.clean_id_google_ad === clean.clean_id_google_adset;
const namingPmax = /\bP\s*MAX\b|PERFORMANCE\s*MAX/.test(namesForDetection);
