// ADR-33 B3: guarda — dropa itens vazios {} (quirk do Merge Meta em cliente sem aquela plataforma).
// Minima e alinhada a decisao Opcao A: NAO dropa por falta de identidade (campanha configurada
// sem dado deve virar linha, nao sumir). Separar no_results real de fantasma vem na B2.
const items = $input.all().filter((it) => it && it.json && Object.keys(it.json).length > 0);
const output = [];

const num = (value) => {
  const n = Number(value ?? 0);
  return Number.isFinite(n) ? n : 0;
};

const round = (value, digits = 2) => {
  const n = num(value);
  return Number(n.toFixed(digits));
};

const div = (numerator, denominator, multiplier = 1, digits = 2) => {
  const den = num(denominator);
  if (den <= 0) return 0;
  return round((num(numerator) / den) * multiplier, digits);
};

const emptyRaw = () => ({
  cost: 0,
  costMicros: 0,
  clicks: 0,
  impressions: 0,
  conversions: 0,
  conversionsValue: 0,
  optScore: 0,
  budget: 0,
  status: 'ESTÁVEL'
});

const addMetrics = (target, metrics = {}) => {
  const costMicros = num(metrics.costMicros ?? metrics.cost_micros);
  target.costMicros += costMicros;
  target.cost += costMicros / 1000000;
  target.clicks += num(metrics.clicks);
  target.impressions += num(metrics.impressions);
  target.conversions += num(metrics.conversions);
  target.conversionsValue += num(metrics.conversionsValue ?? metrics.conversions_value);
};

const aggregateGoogleResponse = (response, campaignId) => {
  const raw = emptyRaw();
  const rows = Array.isArray(response?.results) ? response.results : [];
  const normalizedCampaignId = campaignId ? String(campaignId) : '';

  for (const row of rows) {
    const rowCampaignId = row?.campaign?.id ? String(row.campaign.id) : '';
    if (normalizedCampaignId && rowCampaignId && rowCampaignId !== normalizedCampaignId) continue;

    addMetrics(raw, row.metrics || {});

    if (!raw.optScore && row.campaign?.optimizationScore !== undefined) {
      raw.optScore = num(row.campaign.optimizationScore) * 100;
    }
    if (!raw.budget && row.campaignBudget?.amountMicros !== undefined) {
      raw.budget = num(row.campaignBudget.amountMicros) / 1000000;
    }
    if (row.campaign?.biddingStrategySystemStatus) {
      raw.status = row.campaign.biddingStrategySystemStatus;
    }
  }

  return raw;
};

const fillFromFallback = (raw, fallback = {}) => {
  if (!raw.cost && fallback.cost !== undefined) raw.cost = num(fallback.cost);
  if (!raw.costMicros && fallback.costMicros !== undefined) raw.costMicros = num(fallback.costMicros);
  if (!raw.clicks && fallback.clicks !== undefined) raw.clicks = num(fallback.clicks);
  if (!raw.impressions && fallback.impressions !== undefined) raw.impressions = num(fallback.impressions);
  if (!raw.conversions && fallback.conversions !== undefined) raw.conversions = num(fallback.conversions);
  if (!raw.conversionsValue && fallback.conversionsValue !== undefined) raw.conversionsValue = num(fallback.conversionsValue);
  return raw;
};

// [2026-08-08] VALOR DE CONVERSAO PLACEHOLDER.
// Quando conversions_value ~= conversions, cada conversao vale 1 unidade monetaria
// (default do Google Ads para acao sem valor). Isso NAO e receita: e marcador.
// Calcular ROAS sobre ele produz um numero sem significado (ex.: barbearia lead-gen
// exibindo "ROAS 0,16"). Mesma familia da regra 8 do BLOCO COMUM:
// conversions = 0 => CPA/ROAS INDEFINIDOS, nunca zero.
const receitaEhPlaceholder = (conversionsValue, conversions) => {
  const v = num(conversionsValue);
  const c = num(conversions);
  if (v <= 0) return true;
  return c > 0 && Math.abs(v - c) < 0.01;
};

const calculatePaidMediaMetrics = (raw7, raw30) => {
  const ph7 = receitaEhPlaceholder(raw7.conversionsValue, raw7.conversions);
  const ph30 = receitaEhPlaceholder(raw30.conversionsValue, raw30.conversions);
  return {
  cost_7d: round(raw7.cost, 6),
  cost_30d: round(raw30.cost, 6),
  investimento_7d: round(raw7.cost, 2),
  investimento_30d: round(raw30.cost, 2),

  clicks_7d: raw7.clicks,
  clicks_30d: raw30.clicks,
  impressions_7d: raw7.impressions,
  impressions_30d: raw30.impressions,
  conversions_7d: round(raw7.conversions, 6),
  conversions_30d: round(raw30.conversions, 6),
  revenue_7d: ph7 ? null : round(raw7.conversionsValue, 6),
  revenue_30d: ph30 ? null : round(raw30.conversionsValue, 6),

  cpc_7d: div(raw7.cost, raw7.clicks),
  cpc_30d: div(raw30.cost, raw30.clicks),
  cpa_7d: div(raw7.cost, raw7.conversions),
  cpa_30d: div(raw30.cost, raw30.conversions),
  cpl_7d: div(raw7.cost, raw7.conversions),
  cpl_30d: div(raw30.cost, raw30.conversions),
  ctr_7d: div(raw7.clicks, raw7.impressions, 100),
  ctr_30d: div(raw30.clicks, raw30.impressions, 100),
  cpm_7d: div(raw7.cost, raw7.impressions, 1000),
  cpm_30d: div(raw30.cost, raw30.impressions, 1000),
  cvr_7d: div(raw7.conversions, raw7.clicks, 100),
  cvr_30d: div(raw30.conversions, raw30.clicks, 100),
  taxa_conversao_7d: div(raw7.conversions, raw7.clicks, 100),
  taxa_conversao_30d: div(raw30.conversions, raw30.clicks, 100),
  roas_7d: ph7 ? null : div(raw7.conversionsValue, raw7.cost),
  roas_30d: ph30 ? null : div(raw30.conversionsValue, raw30.cost),

  receita_placeholder_7d: ph7,
  receita_placeholder_30d: ph30
  };
};

const metricValue = (metrics, metricName) => {
  const normalized = String(metricName || '').toLowerCase();
  if (normalized === 'roas') return metrics.roas_7d;
  if (normalized === 'cpc') return metrics.cpc_7d;
  if (normalized === 'ctr') return metrics.ctr_7d;
  if (normalized === 'cpm') return metrics.cpm_7d;
  if (normalized === 'cpl') return metrics.cpl_7d;
  if (normalized === 'taxa de conversão' || normalized === 'taxa de conversao' || normalized === 'cvr') return metrics.cvr_7d;
  if (normalized === 'impressões' || normalized === 'impressoes' || normalized === 'impressions') return metrics.impressions_7d;
  return metrics.cpa_7d;
};

const lowerIsBetter = (metricName) => {
  const normalized = String(metricName || '').toLowerCase();
  return ['cpa', 'cpl', 'cpc', 'cpm', 'cac'].includes(normalized);
};

for (const item of items) {
  const data = item.json;
  const metaValor = num(data.meta_valor ?? data.sop_config?.meta_valor);
  const tipoMetrica = data.sop_config?.metric_principal || data.metric_principal || data.clean_meta_primaria || 'CPA';
  // ADR-33 B1: entity_id (carimbado no gatilho) tem prioridade -> ativa o filtro por campanha
  const campaignId = data.entity_id || data.google_ads_id || data.raw_notion_data?.clean_id_google || data.campaign?.id || data.campaign_id;

  let d7Response = data;
  let d30Response = {};

  try {
    d7Response = $('HTTP Request Google Ontem (D7)').item.json;
  } catch (e) {}

  try {
    d30Response = $('v23 Bloco 1 Core').item.json;
  } catch (e) {
    try {
      d30Response = $('HTTP Request Google (D30)').item.json;
    } catch (e2) {}
  }

  let raw7 = aggregateGoogleResponse(d7Response, campaignId);
  let raw30 = aggregateGoogleResponse(d30Response, campaignId);

  raw7 = fillFromFallback(raw7, {
    cost: data.raw_cost_7d ?? data.raw_cost_d7,
    costMicros: data.raw_cost_micros_7d ?? data.raw_cost_micros_d7,
    clicks: data.raw_clicks_7d,
    impressions: data.raw_impressions_7d,
    conversions: data.raw_conversions_7d,
    conversionsValue: data.raw_conversions_value_7d
  });

  raw30 = fillFromFallback(raw30, {
    cost: data.raw_cost_brl_d30 ?? data.raw_cost_30d,
    costMicros: data.raw_cost_micros_d30 ?? data.raw_cost_micros_30d,
    clicks: data.raw_clicks_d30 ?? data.raw_clicks_30d,
    impressions: data.raw_impressions_d30 ?? data.raw_impressions_30d,
    conversions: data.raw_conversions_d30 ?? data.raw_conversions_30d,
    conversionsValue: data.raw_conversions_value_d30 ?? data.raw_conversions_value_30d
  });

  if (data.calculado && !raw7.cost && !raw7.clicks && !raw7.impressions) {
    raw7 = fillFromFallback(raw7, {
      cost: data.calculado.custo_real,
      clicks: data.calculado.cliques,
      impressions: data.calculado.impressoes,
      conversions: data.calculado.conversoes,
      conversionsValue: data.calculado.valor_conversao
    });
  }

  const metrics = calculatePaidMediaMetrics(raw7, raw30);
  const valorReal = metricValue(metrics, tipoMetrica);

  let statusMeta = 'No Alvo ?';
  if (valorReal === null) {
    // Metrica-mae nao avaliavel (ex.: ROAS sem receita rastreada).
    statusMeta = 'N/D (sem receita rastreada)';
  } else if (metaValor > 0) {
    const isLowerBetter = lowerIsBetter(tipoMetrica);
    if (isLowerBetter) {
      statusMeta = valorReal <= metaValor ? 'No Alvo ✅' : 'Acima da Meta 🚨';
    } else {
      statusMeta = valorReal >= metaValor ? 'No Alvo ✅' : 'Abaixo da Meta 📉';
    }
  }

  output.push({
    json: {
      ...data,
      // ADR-33 B1: identidade resolvida carimbada para downstream casar por chave
      entity_id: campaignId ? String(campaignId) : (data.entity_id || null),
      entity_name: data.entity_name || null,
      platform: data.platform || null,
      valor_real: valorReal === null ? null : round(valorReal, 2),
      meta_estabelecida: metaValor,
      status_meta: statusMeta,
      orcamento_diario: round(raw7.budget, 2),
      aprendizado: String(raw7.status || 'ESTÁVEL').replace(/_/g, ' '),
      opt_score: round(raw7.optScore, 2),

      ...metrics,

      raw_cost_7d: metrics.cost_7d,
      raw_cost_30d: metrics.cost_30d,
      raw_cost_micros_7d: round(raw7.costMicros, 0),
      raw_cost_micros_30d: round(raw30.costMicros, 0),
      raw_clicks_7d: raw7.clicks,
      raw_clicks_30d: raw30.clicks,
      raw_impressions_7d: raw7.impressions,
      raw_impressions_30d: raw30.impressions,
      raw_conversions_7d: metrics.conversions_7d,
      raw_conversions_30d: metrics.conversions_30d,
      raw_conversions_value_7d: metrics.revenue_7d,
      raw_conversions_value_30d: metrics.revenue_30d,

      metricas_calculadas: {
        d7: {
          custo: metrics.cost_7d,
          cliques: metrics.clicks_7d,
          impressoes: metrics.impressions_7d,
          conversoes: metrics.conversions_7d,
          receita: metrics.revenue_7d,
          cpc: metrics.cpc_7d,
          cpa: metrics.cpa_7d,
          cpl: metrics.cpl_7d,
          ctr: metrics.ctr_7d,
          cpm: metrics.cpm_7d,
          cvr: metrics.cvr_7d,
          roas: metrics.roas_7d
        },
        d30: {
          custo: metrics.cost_30d,
          cliques: metrics.clicks_30d,
          impressoes: metrics.impressions_30d,
          conversoes: metrics.conversions_30d,
          receita: metrics.revenue_30d,
          cpc: metrics.cpc_30d,
          cpa: metrics.cpa_30d,
          cpl: metrics.cpl_30d,
          ctr: metrics.ctr_30d,
          cpm: metrics.cpm_30d,
          cvr: metrics.cvr_30d,
          roas: metrics.roas_30d
        }
      }
    }
  });
}

return output;

