// Deriva os campos de diagnostico do brief secao 11 (#2, #3, #4, #5, #9, #10).
// Entrada: saida de "Code classificar status" (metricas unificadas Meta/Google + gate).
// Todos os rotulos usam a GRAFIA EXATA das opcoes do DB "Anuncios" no Notion (pre-req 11.5.1).

// --- Parametros do brief (11.2 / 11.3) ---
const FREQ_ATENCAO = 2.5;
const FREQ_SATURADO = 3.5;
const QUEDA_HOOK_ATENCAO = 20;   // %
const QUEDA_HOOK_SATURADO = 35;  // %
const PESO_RANKINGS = 0.50;
const PESO_HOOK = 0.25;
const PESO_HOLD = 0.25;

// Benchmarks de normalizacao (nao definidos no brief - ajustaveis).
const HOOK_BENCHMARK = 25;  // %
const HOLD_BENCHMARK = 15;  // %
const CTR_BENCHMARK = 1.0;  // %
const CTR_CRITICO = 0.5;    // %
const TEND_LIMIAR = 10;     // % de variacao 3d vs 7d

const RANK_PONTOS = {
  ABOVE_AVERAGE: 100,
  AVERAGE: 60,
  BELOW_AVERAGE_35: 40,
  BELOW_AVERAGE_20: 25,
  BELOW_AVERAGE_10: 10,
};

// Mapas para as opcoes REAIS dos selects no Notion.
// [2026-08-08] "Dados Insuficientes" deixou de existir como estado.
// "Em aprendizado" agora so aparece para anuncio realmente novo (<14d), nunca
// como sinonimo de "gate fechado" -- o rotulo antigo mentia sobre anuncios com
// anos de veiculacao. Rotulos limitados as opcoes existentes dos selects no Notion.
const STATUS_NOTION = {
  'OK': 'Bom',
  'Atenção': 'Atenção',
  'Crítico': 'Crítico',
  'Sem Dados': 'Sem dados',
  'Em Aprendizado': 'Em aprendizado',
};
const PRIORIDADE_NOTION = {
  'Crítico': 'Urgente',
  'Atenção': 'Alta',
  'OK': 'Baixa',
  'Sem Dados': 'Baixa',
  'Em Aprendizado': 'Baixa',
};
// Evidencia parcial nunca gera "Urgente" (mas continua gerando prioridade real).
const REBAIXA_HIPOTESE = { 'Urgente': 'Alta' };

const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const clamp100 = (v) => Math.max(0, Math.min(100, Number.isFinite(v) ? v : 0));

const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;
  const calc = data.calculado || {};
  const analise = data.analise_desvios || {};

  const finalStatus = String(data.final_status || 'Sem Dados');
  const sig = data.significancia || {};
  const suficiente = sig.suficiente === true;
  const confianca = sig.confianca || 'sem_base';
  const nivelEvidencia = sig.nivel || 'nenhum';
  const janelaEvidencia = sig.janela_evidencia || '7d';
  const semBase = finalStatus === 'Sem Dados' || finalStatus === 'Em Aprendizado';

  const frequencia = num(calc.frequencia);
  const hook = num(calc.hook_rate);
  const hold = num(calc.hold_rate);
  const ctr = num(calc.ctr !== undefined ? calc.ctr : data.ctr_7d);

  // Queda de hook_rate vs 7d exige historico (BigQuery). Sem historico fica null.
  const quedaHook = (data.hook_rate_queda_7d === undefined || data.hook_rate_queda_7d === null)
    ? null
    : num(data.hook_rate_queda_7d);

  // ---------- #10 criativo_score_operacional (0-100) ----------
  const ranks = [calc.quality_ranking, calc.engagement_rate_ranking, calc.conversion_rate_ranking]
    .map((r) => RANK_PONTOS[String(r || '').toUpperCase()])
    .filter((p) => p !== undefined);

  const hookNorm = clamp100((hook / HOOK_BENCHMARK) * 100);
  const holdNorm = clamp100((hold / HOLD_BENCHMARK) * 100);
  const temHookHold = hook > 0 || hold > 0;

  let criativo_score = 0;
  let criativo_score_classe = 'Sem dados';

  if (ranks.length > 0) {
    const mediaRanks = ranks.reduce((a, b) => a + b, 0) / ranks.length;
    criativo_score = Math.round(clamp100(mediaRanks * PESO_RANKINGS + hookNorm * PESO_HOOK + holdNorm * PESO_HOLD));
    criativo_score_classe = 'completo';
  } else if (temHookHold) {
    // Rankings vazios (anuncio antigo): 50% hook + 50% hold, marcado como parcial.
    criativo_score = Math.round(clamp100(hookNorm * 0.5 + holdNorm * 0.5));
    criativo_score_classe = 'parcial';
  }

  // ---------- #9 criativo_fadiga_status ----------
  let criativo_fadiga_status = 'Sem dados';
  if (suficiente && frequencia > 0) {
    const quedaAlta = quedaHook !== null && quedaHook > QUEDA_HOOK_SATURADO;
    const quedaAtencao = quedaHook !== null && quedaHook >= QUEDA_HOOK_ATENCAO;
    const ctrAbaixoCritico = ctr > 0 && ctr < CTR_CRITICO;
    const ctrAbaixoBenchmark = ctr > 0 && ctr < CTR_BENCHMARK;

    if (frequencia >= FREQ_SATURADO && (quedaAlta || ctrAbaixoCritico)) {
      criativo_fadiga_status = 'Saturado';
    } else if (frequencia >= FREQ_ATENCAO || quedaAtencao || ctrAbaixoBenchmark) {
      criativo_fadiga_status = 'Atenção';
    } else {
      criativo_fadiga_status = 'Saudável';
    }
  }

  // ---------- #4 ad_status_operacional ----------
  const ad_status_operacional = STATUS_NOTION[finalStatus] || 'Sem dados';

  // ---------- #2 ad_prioridade_otimizacao ----------
  let ad_prioridade_otimizacao = PRIORIDADE_NOTION[finalStatus] || 'Baixa';
  if (confianca === 'hipotese') {
    ad_prioridade_otimizacao = REBAIXA_HIPOTESE[ad_prioridade_otimizacao] || ad_prioridade_otimizacao;
  }

  // ---------- #5 ad_tendencia ----------
  // Convencao: tendencia POSITIVA = piorou.
  // [2026-08-08] SOLTA DO GATE: a tendencia vem da serie diaria (BigQuery, 3d vs 3d)
  // e independe da significancia do desvio. Antes era calculada e descartada.
  // Exige ao menos evidencia PARCIAL (a barra antiga era PLENO, que travava tudo).
  const tendVal = analise.tendencia_3d_vs_7d;
  let ad_tendencia = 'Sem dados';
  if (tendVal !== undefined && tendVal !== null && nivelEvidencia !== 'nenhum') {
    const t = num(tendVal);
    if (t > TEND_LIMIAR) ad_tendencia = 'Piora';
    else if (t < -TEND_LIMIAR) ad_tendencia = 'Melhora';
    else ad_tendencia = 'Estável';
  }

  // ---------- Fora da Meta? (checkbox) ----------
  // [2026-08-08 fase4] Deriva do MESMO status que ja alimenta ad_status_operacional.
  //   Crítico/Atenção -> true (__YES__) · OK -> false (__NO__)
  //   indefinido/Sem Dados/Em Aprendizado -> null: NAO escrever (o Update mantem o valor atual).
  let ad_fora_da_meta = null;
  if (finalStatus === 'Crítico' || finalStatus === 'Atenção') ad_fora_da_meta = true;
  else if (finalStatus === 'OK') ad_fora_da_meta = false;

  // ---------- #3 ad_diagnostico (template por regra) ----------
  const metrica = data.clean_metrica_mae || analise.tipo_metric || 'Métrica-Mãe';
  const desvio7 = num(analise.d7?.desvio);
  const direcao = analise.direcao === 'maior_melhor' ? 'abaixo' : 'acima';
  const absDesvio = Math.abs(Math.round(desvio7 * 10) / 10);

  const selo = nivelEvidencia === 'parcial' ? ' [evidência parcial: ' + janelaEvidencia + ']' : '';
  const sufixoCriativo = criativo_fadiga_status !== 'Sem dados' ? '; criativo ' + criativo_fadiga_status : '';

  let ad_diagnostico;
  if (finalStatus === 'Em Aprendizado') {
    ad_diagnostico = 'Anúncio recém-lançado (' + (sig.dias_desde_lancamento ?? '?') + 'd); aguardando volume para a primeira leitura.';
  } else if (sig.roas_sem_receita) {
    ad_diagnostico = 'ROAS não avaliável: valor de conversão é placeholder (sem receita rastreada). Métrica-mãe deveria ser CPA/CPL.';
  } else if (semBase) {
    ad_diagnostico = 'Volume abaixo do mínimo para leitura — 7d: ' + num(sig.clicks_7d) + ' cliques / ' + num(sig.conversions_7d) +
      ' conv.; 30d: ' + num(sig.clicks_30d) + ' / ' + num(sig.conversions_30d) + ' (mínimo parcial: 30 cliques / 3 conv.).';
  } else if (desvio7 <= 0) {
    ad_diagnostico = 'Dentro da meta (' + metrica + ' desvio ' + absDesvio + '% em 7d); tendência ' + ad_tendencia + selo + sufixoCriativo + '.';
  } else {
    ad_diagnostico = metrica + ' ' + absDesvio + '% ' + direcao + ' da meta em 7d; tendência ' + ad_tendencia + selo + sufixoCriativo + '.';
  }

  output.push({
    json: {
      ...data,
      criativo_fadiga_status,
      criativo_score_operacional: criativo_score,
      criativo_score_classe,
      ad_status_operacional,
      ad_prioridade_otimizacao,
      ad_tendencia,
      ad_diagnostico,
      ad_fora_da_meta,
      confianca_leitura: confianca,
      janela_evidencia: janelaEvidencia,
      diagnostico_sinais: {
        nivel_evidencia: nivelEvidencia,
        janela_evidencia: janelaEvidencia,
        confianca,
        frequencia,
        hook_rate: hook,
        hold_rate: hold,
        ctr,
        hook_rate_queda_7d: quedaHook,
        rankings_encontrados: ranks.length,
        gate_suficiente: suficiente,
        final_status: finalStatus,
        final_score: data.final_score ?? null,
      },
    },
  });
}

return output;

// Pre-requisito 11.5.2: persistir os sinais de criativo TAMBEM no BigQuery.
// O Modulo 28 le o BigQuery; sem isso o agente Diagnostico nao enxerga hook/hold/rankings/fadiga.
// Grava em phi_prod.raw_ad_data (mesma chave da ingestao ad-grain).

const items = $input.all();
const output = [];

const sqlStr = (v) => "'" + String(v == null ? '' : v).replace(/'/g, "''") + "'";
const sqlStrOrNull = (v) => (v === undefined || v === null || v === '') ? 'NULL' : sqlStr(v);
const sqlNumOrNull = (v) => {
  if (v === undefined || v === null || v === '') return 'NULL';
  const n = Number(v);
  return Number.isFinite(n) ? String(n) : 'NULL';
};
const sqlNum = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? String(n) : '0';
};

const firstResult = (nodeName) => {
  try { return $(nodeName).item.json.results?.[0] || {}; } catch (e) { return {}; }
};
const nodeJson = (nodeName) => {
  try { return $(nodeName).item.json || {}; } catch (e) { return {}; }
};

// O contexto do Notion nao sobrevive as chamadas HTTP: ler do produtor original.
const cleanProps = nodeJson('Code clean propriedades');

for (const item of items) {
  const data = item.json;
  // calculado pode ter sido substituido no caminho: cair para o produtor Meta quando faltar.
  const calc = (data.calculado && Object.keys(data.calculado).length)
    ? data.calculado
    : (nodeJson('Code Cálculo Dados Meta').calculado || {});

  const plataforma = data.clean_plataforma || cleanProps.clean_plataforma || '';
  const ehMeta = /meta/i.test(String(plataforma));

  // --- Resolve a chave (mesma semantica da ingestao principal) ---
  let campaignId = '';
  let adsetId = '';
  let adId = '';

  if (ehMeta) {
    adId = String(calc.ad_id || '');
    adsetId = String(calc.adset_id || '');
    campaignId = calc.campaign_id ? 'META-' + calc.campaign_id : '';
  } else {
    const rD1 = firstResult('HTTP Request Google Ontem (D1)');
    const gCamp = rD1.campaign?.id || '';
    adsetId = String(rD1.adGroup?.id || '');
    adId = String(rD1.adGroupAd?.ad?.id || '');
    campaignId = gCamp ? 'GADS-' + gCamp : '';
  }

  // Sem chave completa nao ha linha ad-grain para enriquecer (ex.: PMAX). Nao emite item.
  if (!adId || !campaignId || !adsetId) {
    continue;
  }

  const clientId = data.clean_client_slug || cleanProps.clean_client_slug || data.client_id || '';
  const executionId = data.source_execution_id ||
    ('EXEC-DIAG-' + new Date().toISOString().replace(/[-:TZ.]/g, '').slice(0, 14));

  // Sinais de video/ranking so existem no Meta: no Google gravamos NULL (e nao 0, que enganaria).
  const frequency = ehMeta ? sqlNumOrNull(calc.frequencia) : 'NULL';
  const hookRate = ehMeta ? sqlNumOrNull(calc.hook_rate) : 'NULL';
  const holdRate = ehMeta ? sqlNumOrNull(calc.hold_rate) : 'NULL';
  const videoIni = ehMeta ? sqlNumOrNull(calc.video_iniciados) : 'NULL';
  const video50 = ehMeta ? sqlNumOrNull(calc.video_50) : 'NULL';
  const videoFim = ehMeta ? sqlNumOrNull(calc.video_completos) : 'NULL';
  const qRank = ehMeta ? sqlStrOrNull(calc.quality_ranking) : 'NULL';
  const eRank = ehMeta ? sqlStrOrNull(calc.engagement_rate_ranking) : 'NULL';
  const cRank = ehMeta ? sqlStrOrNull(calc.conversion_rate_ranking) : 'NULL';
  const msgConv = ehMeta ? sqlNumOrNull(calc.message_conversations) : 'NULL';
  const cpmVal = ehMeta ? sqlNumOrNull(calc.cpm) : 'NULL';
  const roasVal = ehMeta ? sqlNumOrNull(calc.roas) : 'NULL';

  // Diagnostico e calculado para os dois caminhos.
  const fadiga = sqlStr(data.criativo_fadiga_status || 'Sem dados');
  const criativoScore = sqlNum(data.criativo_score_operacional);

  const sql = 'MERGE phi_prod.raw_ad_data AS target\n' +
    'USING (\n' +
    '  SELECT\n' +
    '    ' + sqlStr(executionId) + ' AS execution_id,\n' +
    '    ' + sqlStr(clientId) + ' AS client_id,\n' +
    '    ' + sqlStr(campaignId) + ' AS campaign_id,\n' +
    '    ' + sqlStr(adsetId) + ' AS adset_id,\n' +
    '    ' + sqlStr(adId) + ' AS ad_id,\n' +
    "    DATE_SUB(CURRENT_DATE('America/Sao_Paulo'), INTERVAL 1 DAY) AS date,\n" +
    '    ' + frequency + ' AS frequency,\n' +
    '    ' + hookRate + ' AS hook_rate,\n' +
    '    ' + holdRate + ' AS hold_rate,\n' +
    '    ' + videoIni + ' AS video_iniciados,\n' +
    '    ' + video50 + ' AS video_50,\n' +
    '    ' + videoFim + ' AS video_completos,\n' +
    '    ' + qRank + ' AS quality_ranking,\n' +
    '    ' + eRank + ' AS engagement_rate_ranking,\n' +
    '    ' + cRank + ' AS conversion_rate_ranking,\n' +
    '    ' + msgConv + ' AS message_conversations,\n' +
    '    ' + cpmVal + ' AS cpm,\n' +
    '    ' + roasVal + ' AS roas,\n' +
    '    ' + fadiga + ' AS criativo_fadiga_status,\n' +
    '    ' + criativoScore + ' AS criativo_score_operacional\n' +
    ') AS source\n' +
    'ON  target.client_id   = source.client_id\n' +
    'AND target.campaign_id = source.campaign_id\n' +
    'AND target.adset_id    = source.adset_id\n' +
    'AND target.ad_id       = source.ad_id\n' +
    'AND target.date        = source.date\n' +
    'WHEN MATCHED THEN UPDATE SET\n' +
    '  target.frequency = source.frequency,\n' +
    '  target.hook_rate = source.hook_rate,\n' +
    '  target.hold_rate = source.hold_rate,\n' +
    '  target.video_iniciados = source.video_iniciados,\n' +
    '  target.video_50 = source.video_50,\n' +
    '  target.video_completos = source.video_completos,\n' +
    '  target.quality_ranking = source.quality_ranking,\n' +
    '  target.engagement_rate_ranking = source.engagement_rate_ranking,\n' +
    '  target.conversion_rate_ranking = source.conversion_rate_ranking,\n' +
    '  target.message_conversations = source.message_conversations,\n' +
    '  target.cpm = source.cpm,\n' +
    '  target.roas = source.roas,\n' +
    '  target.criativo_fadiga_status = source.criativo_fadiga_status,\n' +
    '  target.criativo_score_operacional = source.criativo_score_operacional,\n' +
    '  target.ingested_at = CURRENT_TIMESTAMP()\n' +
    'WHEN NOT MATCHED THEN INSERT (\n' +
    '  execution_id, client_id, campaign_id, adset_id, ad_id, date,\n' +
    '  frequency, hook_rate, hold_rate, video_iniciados, video_50, video_completos,\n' +
    '  quality_ranking, engagement_rate_ranking, conversion_rate_ranking,\n' +
    '  message_conversations, cpm, roas,\n' +
    '  criativo_fadiga_status, criativo_score_operacional,\n' +
    '  data_source, platform, ingestion_status, ingestion_step, ingested_at\n' +
    ') VALUES (\n' +
    '  source.execution_id, source.client_id, source.campaign_id, source.adset_id, source.ad_id, source.date,\n' +
    '  source.frequency, source.hook_rate, source.hold_rate, source.video_iniciados, source.video_50, source.video_completos,\n' +
    '  source.quality_ranking, source.engagement_rate_ranking, source.conversion_rate_ranking,\n' +
    '  source.message_conversations, source.cpm, source.roas,\n' +
    '  source.criativo_fadiga_status, source.criativo_score_operacional,\n' +
    '  ' + sqlStr(ehMeta ? 'meta_ads_api' : 'google_ads_api') + ', ' + sqlStr(ehMeta ? 'meta_ads' : 'google_ads') + ", 'SUCCESS', 'DIAGNOSTICO_CRIATIVO', CURRENT_TIMESTAMP()\n" +
    ');';

  output.push({ json: { ...data, _bq_sql_criativo: sql, _bq_criativo_key: { campaignId, adsetId, adId, ehMeta, plataforma, clientId } } });
}

return output;
